def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    aggressive_count = 0
    desperate_count = 0

    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            if prev:
                bid = prev.get('bid')
                if bid is not None:
                    prev_bids.append(bid)
                    if bid >= 100:
                        aggressive_count += 1

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = 0
    if supply <= 16:
        scarcity = 2
    elif supply <= 19:
        scarcity = 1

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2

    if day >= 8 and hp <= 5:
        urgency += 1

    if urgency >= 5:
        bid = max(95.0, highest_prev + 4.0)
    elif urgency >= 3:
        bid = max(62.0 + 8.0 * scarcity, avg_prev * 0.72 + 6.0)
    else:
        if supply >= 22:
            bid = 22.0
        elif supply >= 19:
            bid = 30.0
        else:
            bid = 40.0

        if highest_prev > 0:
            if highest_prev >= 140:
                bid = min(bid, 36.0 + 4.0 * scarcity)
            elif highest_prev >= 100:
                bid = max(bid, 44.0 + 5.0 * scarcity)
            elif highest_prev >= 70:
                bid = max(bid, highest_prev * 0.68)
            else:
                bid = max(bid, highest_prev + 2.0)

    if aggressive_count >= 2 and urgency <= 2:
        bid *= 0.88
    if desperate_count >= 2 and scarcity >= 1:
        bid += 8.0

    reserve = 0.0
    if hp > 4 and day <= 7:
        reserve = 25.0
    elif hp > 2:
        reserve = 10.0

    cap = budget - reserve
    if urgency >= 4:
        cap = budget
    if cap < 0:
        cap = 0.0

    bid = min(bid, cap)

    if urgency >= 4 and bid < 55.0 and budget >= 55.0:
        bid = min(budget, 55.0 + 5.0 * scarcity)

    if bid < 0:
        bid = 0.0

    return float(round(min(budget, bid), 2))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if not yesterday_bids:
        return min(my_status['budget'], DAILY_SALARY * 0.6)

    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids)

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 1.2)

    if supply < WATER_REQ * len(alive_opponents) / 2:
        return min(my_status['budget'], avg_prev_bid * 1.1)

    return min(my_status['budget'], max(DAILY_SALARY * 0.5, avg_prev_bid * 0.95))
